// Generated by tracing a public-domain scan of Katsushika Hokusai's "Under the Wave off Kanagawa"
// (c. 1831): the print separated into its inks, each ink traced into vector rings, as a printer
// would cut one block per colour. Do not edit by hand.
//
// Each block's rings are base64 zigzag varints: [count, x0, y0, dx1, dy1, ...] in 1/4 world px,
// the first point of each ring relative to the last point of the previous one.
// The sky is a 370x250 JPEG, smoothed from every pixel of the sky alone, so no blue bleeds into it.

export const Q = 4;
export const SKY_W = 370;
export const SKY_H = 250;
